// The TS mirror must agree with crates/rules `check_bag_layout` on every fixture case
// (generated by crates/rules/tests/bag_ts_fixtures.rs); the moves never leave the check.
import { describe, expect, it } from "vitest";
import fixture from "./__fixtures__/bag-layout.json";
import {
  CONSUMABLE_STACK_MAX,
  RESOURCE_STACK_MAX,
  checkBagLayout,
  discard,
  emptyBag,
  layoutArgs,
  loadLocks,
  moveSlot,
  replace,
  saveLocks,
  split,
  take,
  type Bag,
  type BagState,
} from "./bagLayout";
import type { Reward } from "./loot";

const r = ([kind, id, qty]: number[]): Reward => ({ kind: kind!, id: id!, qty: qty! });
const bagOf = (b: { resources: number[][]; consumables: number[][] }): Bag => ({ resources: b.resources.map(r), consumables: b.consumables.map(r) });
const [RES, RECIPE, CONS] = [0, 1, 2];
const R = (section: "resources" | "consumables", index: number) => ({ section, index });

describe("bag layout check (fixture from crates/rules)", () => {
  it("has the Rust stack limits", () => {
    expect([RESOURCE_STACK_MAX, CONSUMABLE_STACK_MAX]).toEqual([fixture.resourceStackMax, fixture.consumableStackMax]);
  });

  it("agrees with check_bag_layout on every case", () => {
    for (const c of fixture.cases) {
      expect(checkBagLayout(bagOf(c.before), c.cache.map(r), bagOf(c.after)), JSON.stringify(c)).toBe(c.err);
    }
  });
});

describe("bag moves", () => {
  const start = (cache: Reward[], bag = emptyBag()): BagState => ({ bag, cache });
  const valid = (before: Bag, cache: Reward[], s: BagState | null) => {
    expect(s).not.toBeNull();
    expect(checkBagLayout(before, cache, s!.bag)).toBeNull();
    return s!;
  };

  it("Shift + click fills partial stacks first, then empty slots, a stack at most", () => {
    const bag = emptyBag();
    bag.resources[3] = { kind: RES, id: 1, qty: 7 };
    const cache = [{ kind: RES, id: 1, qty: 15 }];
    const s = valid(bag, cache, take(start(cache, bag), 0, null));
    expect(s.bag.resources[3]!.qty).toBe(10);
    expect(s.bag.resources[0]).toEqual({ kind: RES, id: 1, qty: 10 });
    expect(s.bag.resources[1]).toEqual({ kind: RES, id: 1, qty: 2 });
    expect(s.cache).toEqual([]);
  });

  it("consumables go to their own slots, five at most", () => {
    const cache = [{ kind: CONS, id: 0, qty: 7 }];
    const s = valid(emptyBag(), cache, take(start(cache), 0, null));
    expect(s.bag.consumables.slice(0, 2).map((x) => x.qty)).toEqual([5, 2]);
    expect(take(start(cache), 0, R("resources", 0))).toBeNull();
  });

  it("takes part of a stack into a chosen slot", () => {
    const cache = [{ kind: RECIPE, id: 4, qty: 3 }];
    const s = valid(emptyBag(), cache, take(start(cache), 0, R("resources", 9), 1));
    expect(s.bag.resources[9]).toEqual({ kind: RECIPE, id: 4, qty: 1 });
    expect(s.cache).toEqual([{ kind: RECIPE, id: 4, qty: 2 }]);
  });

  it("replace: the bag's reward goes back into the cache in its place", () => {
    const bag = emptyBag();
    bag.resources[0] = { kind: RES, id: 2, qty: 4 };
    const cache = [{ kind: RES, id: 5, qty: 12 }];
    const s = valid(bag, cache, replace(start(cache, bag), 0, R("resources", 0)));
    expect(s.bag.resources[0]).toEqual({ kind: RES, id: 5, qty: 10 });
    expect(s.cache).toEqual([
      { kind: RES, id: 5, qty: 2 },
      { kind: RES, id: 2, qty: 4 },
    ]);
  });

  it("a locked slot is never replaced nor thrown away", () => {
    const bag = emptyBag();
    bag.resources[0] = { kind: RES, id: 2, qty: 4 };
    const locks = new Set(["r:0"]);
    const s = start([{ kind: RES, id: 5, qty: 1 }], bag);
    expect(replace(s, 0, R("resources", 0), locks)).toBeNull();
    expect(discard(s, R("resources", 0), locks)).toBeNull();
    // Shift + click goes around it.
    expect(take(s, 0, null, undefined, locks)!.bag.resources[1]).toEqual({ kind: RES, id: 5, qty: 1 });
  });

  it("moves, merges and swaps slots; splits a stack", () => {
    const bag = emptyBag();
    bag.resources[0] = { kind: RES, id: 1, qty: 6 };
    bag.resources[1] = { kind: RES, id: 1, qty: 7 };
    bag.resources[2] = { kind: RECIPE, id: 0, qty: 1 };
    let s = valid(bag, [], moveSlot(start([], bag), R("resources", 0), R("resources", 1)));
    expect([s.bag.resources[0]!.qty, s.bag.resources[1]!.qty]).toEqual([3, 10]);
    s = valid(bag, [], moveSlot(s, R("resources", 2), R("resources", 0)));
    expect(s.bag.resources[0]!.kind).toBe(RECIPE);
    expect(s.bag.resources[2]).toEqual({ kind: RES, id: 1, qty: 3 });
    s = valid(bag, [], split(s, R("resources", 1)));
    expect([s.bag.resources[1]!.qty, s.bag.resources[3]!.qty]).toEqual([5, 5]);
    expect(moveSlot(s, R("resources", 0), R("consumables", 0))).toBeNull();
  });

  it("throws a slot away; the layout for close_cache has all-zero empty slots", () => {
    const bag = emptyBag();
    bag.resources[0] = { kind: RES, id: 1, qty: 6 };
    const s = valid(bag, [], discard(start([], bag), R("resources", 0)));
    expect(s.bag.resources[0]!.qty).toBe(0);
    const dirty = emptyBag();
    dirty.resources[0] = { kind: RECIPE, id: 3, qty: 0 };
    expect(layoutArgs(dirty).resources[0]).toEqual({ kind: 0, id: 0, qty: 0 });
  });

  it("keeps the slot locks per character in this browser", () => {
    saveLocks("A", new Set(["r:1", "c:0"]));
    expect([...loadLocks("A")].sort()).toEqual(["c:0", "r:1"]);
    expect(loadLocks("B").size).toBe(0);
  });
});
